class Solution { companion object{const val MOD=1_000_000_007L};private lateinit var children:Array<MutableList<Int>>;private lateinit var factorial:LongArray;private lateinit var inverse:LongArray;private fun power(baseValue:Long,exponentValue:Long):Long{var base=baseValue;var exponent=exponentValue;var result=1L;while(exponent>0){if(exponent and 1L==1L)result=result*base%MOD;base=base*base%MOD;exponent=exponent shr 1};return result};private fun choose(n:Int,k:Int)=factorial[n]*inverse[k]%MOD*inverse[n-k]%MOD;private fun dfs(node:Int):LongArray{var ways=1L;var size=1;for(child in children[node]){val result=dfs(child);ways=ways*result[1]%MOD*choose(size+result[0].toInt()-1,result[0].toInt())%MOD;size+=result[0].toInt()};return longArrayOf(size.toLong(),ways)};fun waysToBuildRooms(prevRoom:IntArray):Int{val n=prevRoom.size;children=Array(n){mutableListOf()};for(i in 1 until n)children[prevRoom[i]].add(i);factorial=LongArray(n+1);inverse=LongArray(n+1);factorial[0]=1;for(i in 1..n)factorial[i]=factorial[i-1]*i%MOD;inverse[n]=power(factorial[n],MOD-2);for(i in n downTo 1)inverse[i-1]=inverse[i]*i%MOD;return dfs(0)[1].toInt()} }
